        let mut owner = DispatchGenerationOwnerV1::new().unwrap();
        let first_generation = owner.next().unwrap();
        owner.commit_begin(first_generation);
        owner.complete(first_generation).unwrap();
        owner.recycle(first_generation).unwrap();

